body.script:
//
                    document.addEventListener('DOMContentLoaded', function () {
                        var table = document.getElementById('o_sd_table');
                        var thead = table.tHead;
                        var headerRow = thead.rows[0];
                        var tbody = table.tBodies[0];
                        var totalsRow = document.getElementById('o_sd_totals_row');
                        var scrollEl = document.querySelector('.o_sd_scroll');
                        var rows = Array.prototype.slice.call(tbody.rows);
                        var colCount = headerRow.cells.length;

                        // One <col> per column lets a whole column (header, every
                        // body cell, totals cell) be hidden in one shot via
                        // visibility:collapse, instead of touching every <td>.
                        var colgroup = document.createElement('colgroup');
                        for (var gi = 0; gi < colCount; gi++) {
                            colgroup.appendChild(document.createElement('col'));
                        }
                        table.insertBefore(colgroup, table.firstChild);
                        var cols = colgroup.children;
                        var hiddenCols = {};
                        // S.No / Emp Code / Name are the pinned identity columns - hiding
                        // one would leave a gap since the others' sticky "left" offsets
                        // are fixed pixel values, not recalculated around visible
                        // siblings. Simplest safe rule: keep them always visible.
                        var PINNED_COL_COUNT = 3;

                        function setColumnVisibility(colIdx, visible) {
                            if (colIdx < PINNED_COL_COUNT) { return; }
                            cols[colIdx].style.visibility = visible ? '' : 'collapse';
                            if (visible) { delete hiddenCols[colIdx]; } else { hiddenCols[colIdx] = true; }
                        }

                        // columnFilters[colIdx] = Set of currently-selected (checked)
                        // values for that column. No entry = no filter = show all,
                        // exactly like Excel/Sheets treats "everything checked".
                        var columnFilters = {};
                        var globalFilter = '';
                        var uniqueValuesCache = {};

                        function decimalsOf(text) {
                            var i = text.indexOf('.');
                            return i === -1 ? 0 : (text.length - i - 1);
                        }

                        function compareValues(a, b) {
                            var an = parseFloat(a), bn = parseFloat(b);
                            if (a !== '' && b !== '' && !isNaN(an) && !isNaN(bn)) { return an - bn; }
                            return a.localeCompare(b);
                        }

                        function getUniqueValues(colIdx) {
                            if (uniqueValuesCache[colIdx]) { return uniqueValuesCache[colIdx]; }
                            var seen = {};
                            rows.forEach(function (row) {
                                var text = row.cells[colIdx] ? row.cells[colIdx].textContent.trim() : '';
                                seen[text] = true;
                            });
                            var values = Object.keys(seen).sort(compareValues);
                            uniqueValuesCache[colIdx] = values;
                            return values;
                        }

                        function updateFilterButtonState() {
                            for (var i = 0; i < colCount; i++) {
                                var btn = headerRow.cells[i].querySelector('.o_sd_filter_btn');
                                if (btn) { btn.classList.toggle('o_sd_filter_active', !!columnFilters[i]); }
                            }
                        }

                        function applyFilters() {
                            var visibleCount = 0;
                            rows.forEach(function (row) {
                                var visible = true;
                                for (var i = 0; i < colCount; i++) {
                                    var filterSet = columnFilters[i];
                                    if (!filterSet) { continue; }
                                    var cellText = row.cells[i] ? row.cells[i].textContent.trim() : '';
                                    if (!filterSet.has(cellText)) { visible = false; break; }
                                }
                                if (visible && globalFilter) {
                                    visible = row.textContent.toLowerCase().indexOf(globalFilter) !== -1;
                                }
                                row.classList.toggle('o_sd_row_hidden', !visible);
                                if (visible) { visibleCount++; }
                            });
                            document.getElementById('o_sd_row_count').textContent =
                                'Showing ' + visibleCount + ' of ' + rows.length + ' rows';
                            recomputeTotals();
                        }

                        function recomputeTotals() {
                            // The totals row's leading "Total" cell has colspan=10,
                            // collapsing 10 columns into one DOM cell - totalsRow.cells'
                            // own indices don't line up with body rows' cells (which
                            // have no colspan). Track the running visual column instead
                            // by accumulating each cell's own span.
                            var visualCol = 0;
                            Array.prototype.forEach.call(totalsRow.cells, function (td) {
                                var span = td.colSpan || 1;
                                var field = td.getAttribute('data-sum-field');
                                if (field) {
                                    var idx = visualCol;
                                    var decimals = decimalsOf(td.textContent.trim());
                                    var sum = 0;
                                    rows.forEach(function (row) {
                                        if (row.classList.contains('o_sd_row_hidden')) { return; }
                                        var raw = row.cells[idx] ? row.cells[idx].textContent : '0';
                                        var n = parseFloat(raw.replace(/,/g, ''));
                                        if (!isNaN(n)) { sum += n; }
                                    });
                                    td.textContent = sum.toFixed(decimals);
                                }
                                visualCol += span;
                            });
                        }

                        function sortByColumn(idx, dir) {
                            rows = rows.slice().sort(function (a, b) {
                                var av = (a.cells[idx] ? a.cells[idx].textContent : '').trim();
                                var bv = (b.cells[idx] ? b.cells[idx].textContent : '').trim();
                                return compareValues(av, bv) * dir;
                            });
                            rows.forEach(function (row) { tbody.appendChild(row); });
                        }

                        // ── Excel/Sheets-style per-column filter dropdown ────────────
                        var activePanel = null;
                        var activeColIdx = null;

                        function closePanel() {
                            if (activePanel) {
                                activePanel.remove();
                                activePanel = null;
                                activeColIdx = null;
                            }
                        }

                        function positionPanel(panel, anchorEl) {
                            var rect = anchorEl.getBoundingClientRect();
                            var panelWidth = 260;
                            var left = Math.min(rect.left, window.innerWidth - panelWidth - 8);
                            panel.style.top = (rect.bottom + 4) + 'px';
                            panel.style.left = Math.max(8, left) + 'px';
                        }

                        function buildFilterPanel(colIdx) {
                            var panel = document.createElement('div');
                            panel.className = 'o_sd_filter_panel';

                            var sortAsc = document.createElement('button');
                            sortAsc.type = 'button';
                            sortAsc.className = 'o_sd_fp_sort';
                            sortAsc.textContent = '↑ Sort A to Z';
                            sortAsc.addEventListener('click', function () { sortByColumn(colIdx, 1); closePanel(); });
                            panel.appendChild(sortAsc);

                            var sortDesc = document.createElement('button');
                            sortDesc.type = 'button';
                            sortDesc.className = 'o_sd_fp_sort';
                            sortDesc.textContent = '↓ Sort Z to A';
                            sortDesc.addEventListener('click', function () { sortByColumn(colIdx, -1); closePanel(); });
                            panel.appendChild(sortDesc);

                            if (colIdx >= PINNED_COL_COUNT) {
                                var hideColBtn = document.createElement('button');
                                hideColBtn.type = 'button';
                                hideColBtn.className = 'o_sd_fp_hide_col';
                                hideColBtn.textContent = '🚫 Hide column';
                                hideColBtn.addEventListener('click', function () {
                                    setColumnVisibility(colIdx, false);
                                    closePanel();
                                });
                                panel.appendChild(hideColBtn);
                            }

                            panel.appendChild(document.createElement('hr')).className = 'o_sd_fp_sep';

                            var searchBox = document.createElement('input');
                            searchBox.type = 'text';
                            searchBox.className = 'o_sd_fp_search';
                            searchBox.placeholder = 'Search values';
                            panel.appendChild(searchBox);

                            var actions = document.createElement('div');
                            actions.className = 'o_sd_fp_actions';
                            var selectAllLink = document.createElement('a');
                            selectAllLink.textContent = 'Select all';
                            var clearLink = document.createElement('a');
                            clearLink.textContent = 'Clear';
                            actions.appendChild(selectAllLink);
                            actions.appendChild(document.createTextNode('·'));
                            actions.appendChild(clearLink);
                            panel.appendChild(actions);

                            var list = document.createElement('div');
                            list.className = 'o_sd_fp_list';
                            panel.appendChild(list);

                            var allValues = getUniqueValues(colIdx);
                            var existingFilter = columnFilters[colIdx];
                            var pendingSelection = existingFilter ? new Set(existingFilter) : new Set(allValues);

                            function renderList(filterText) {
                                list.innerHTML = '';
                                var lower = (filterText || '').toLowerCase();
                                allValues.forEach(function (val) {
                                    var label = val === '' ? '(Blanks)' : val;
                                    if (lower && label.toLowerCase().indexOf(lower) === -1) { return; }
                                    var item = document.createElement('label');
                                    item.className = 'o_sd_fp_item';
                                    var cb = document.createElement('input');
                                    cb.type = 'checkbox';
                                    cb.checked = pendingSelection.has(val);
                                    cb.addEventListener('change', function () {
                                        if (cb.checked) { pendingSelection.add(val); } else { pendingSelection.delete(val); }
                                    });
                                    var span = document.createElement('span');
                                    span.textContent = label;
                                    item.appendChild(cb);
                                    item.appendChild(span);
                                    list.appendChild(item);
                                });
                            }
                            renderList('');

                            searchBox.addEventListener('input', function () { renderList(searchBox.value); });
                            searchBox.addEventListener('click', function (ev) { ev.stopPropagation(); });

                            selectAllLink.addEventListener('click', function (ev) {
                                ev.preventDefault();
                                allValues.forEach(function (v) { pendingSelection.add(v); });
                                renderList(searchBox.value);
                            });
                            clearLink.addEventListener('click', function (ev) {
                                ev.preventDefault();
                                pendingSelection.clear();
                                renderList(searchBox.value);
                            });

                            var footer = document.createElement('div');
                            footer.className = 'o_sd_fp_footer';
                            var cancelBtn = document.createElement('button');
                            cancelBtn.type = 'button';
                            cancelBtn.textContent = 'Cancel';
                            cancelBtn.addEventListener('click', function () { closePanel(); });
                            var okBtn = document.createElement('button');
                            okBtn.type = 'button';
                            okBtn.className = 'o_sd_fp_ok';
                            okBtn.textContent = 'OK';
                            okBtn.addEventListener('click', function () {
                                if (pendingSelection.size >= allValues.length) {
                                    delete columnFilters[colIdx];
                                } else {
                                    columnFilters[colIdx] = pendingSelection;
                                }
                                applyFilters();
                                updateFilterButtonState();
                                closePanel();
                            });
                            footer.appendChild(cancelBtn);
                            footer.appendChild(okBtn);
                            panel.appendChild(footer);

                            panel.addEventListener('click', function (ev) { ev.stopPropagation(); });
                            return panel;
                        }

                        function toggleFilterPanel(colIdx, anchorEl) {
                            if (activePanel && activeColIdx === colIdx) {
                                closePanel();
                                return;
                            }
                            closePanel();
                            activeColIdx = colIdx;
                            var panel = buildFilterPanel(colIdx);
                            document.body.appendChild(panel);
                            positionPanel(panel, anchorEl);
                            activePanel = panel;
                            var searchInput = panel.querySelector('.o_sd_fp_search');
                            if (searchInput) { searchInput.focus(); }
                        }

                        // ── Master "Columns" panel: show/hide any column, and bring
                        // back ones hidden via the per-column "Hide column" action ──
                        function buildColumnsPanel() {
                            var panel = document.createElement('div');
                            panel.className = 'o_sd_filter_panel';

                            var searchBox = document.createElement('input');
                            searchBox.type = 'text';
                            searchBox.className = 'o_sd_fp_search';
                            searchBox.placeholder = 'Search columns';
                            panel.appendChild(searchBox);

                            var actions = document.createElement('div');
                            actions.className = 'o_sd_fp_actions';
                            var showAllLink = document.createElement('a');
                            showAllLink.textContent = 'Show all';
                            var hideAllLink = document.createElement('a');
                            hideAllLink.textContent = 'Hide all';
                            actions.appendChild(showAllLink);
                            actions.appendChild(document.createTextNode('·'));
                            actions.appendChild(hideAllLink);
                            panel.appendChild(actions);

                            var list = document.createElement('div');
                            list.className = 'o_sd_fp_list';
                            panel.appendChild(list);

                            function renderList(filterText) {
                                list.innerHTML = '';
                                var lower = (filterText || '').toLowerCase();
                                for (var i = 0; i < colCount; i++) {
                                    (function (idx) {
                                        var label = columnLabels[idx] || ('Column ' + (idx + 1));
                                        if (lower && label.toLowerCase().indexOf(lower) === -1) { return; }
                                        var pinned = idx < PINNED_COL_COUNT;
                                        var item = document.createElement('label');
                                        item.className = 'o_sd_fp_item' + (pinned ? ' o_sd_fp_item_disabled' : '');
                                        var cb = document.createElement('input');
                                        cb.type = 'checkbox';
                                        cb.checked = !hiddenCols[idx];
                                        cb.disabled = pinned;
                                        cb.addEventListener('change', function () {
                                            setColumnVisibility(idx, cb.checked);
                                        });
                                        var span = document.createElement('span');
                                        span.textContent = label + (pinned ? ' (always shown)' : '');
                                        item.appendChild(cb);
                                        item.appendChild(span);
                                        list.appendChild(item);
                                    })(i);
                                }
                            }
                            renderList('');

                            searchBox.addEventListener('input', function () { renderList(searchBox.value); });
                            searchBox.addEventListener('click', function (ev) { ev.stopPropagation(); });

                            showAllLink.addEventListener('click', function (ev) {
                                ev.preventDefault();
                                for (var i = PINNED_COL_COUNT; i < colCount; i++) { setColumnVisibility(i, true); }
                                renderList(searchBox.value);
                            });
                            hideAllLink.addEventListener('click', function (ev) {
                                ev.preventDefault();
                                for (var i = PINNED_COL_COUNT; i < colCount; i++) { setColumnVisibility(i, false); }
                                renderList(searchBox.value);
                            });

                            panel.addEventListener('click', function (ev) { ev.stopPropagation(); });
                            return panel;
                        }

                        function toggleColumnsPanel(anchorEl) {
                            if (activePanel && activeColIdx === 'columns') {
                                closePanel();
                                return;
                            }
                            closePanel();
                            activeColIdx = 'columns';
                            var panel = buildColumnsPanel();
                            document.body.appendChild(panel);
                            positionPanel(panel, anchorEl);
                            activePanel = panel;
                            var searchInput = panel.querySelector('.o_sd_fp_search');
                            if (searchInput) { searchInput.focus(); }
                        }

                        document.addEventListener('click', function (ev) {
                            if (activePanel && !activePanel.contains(ev.target)) { closePanel(); }
                        });
                        document.addEventListener('keydown', function (ev) {
                            if (ev.key === 'Escape') { closePanel(); }
                        });
                        scrollEl.addEventListener('scroll', closePanel);
                        window.addEventListener('scroll', closePanel);
                        window.addEventListener('resize', closePanel);

                        var columnLabels = [];
                        for (var c = 0; c < colCount; c++) {
                            (function (idx) {
                                var th = headerRow.cells[idx];
                                columnLabels[idx] = th.textContent.trim();
                                th.classList.add('o_sd_sortable');
                                var btn = document.createElement('span');
                                btn.className = 'o_sd_filter_btn';
                                btn.textContent = '▾';
                                btn.title = 'Filter / Sort';
                                btn.addEventListener('click', function (ev) {
                                    ev.stopPropagation();
                                    toggleFilterPanel(idx, btn);
                                });
                                th.appendChild(btn);
                            })(c);
                        }

                        // ── Toolbar: global search + clear-all ───────────────────────
                        var globalSearchEl = document.getElementById('o_sd_global_search');
                        globalSearchEl.addEventListener('input', function () {
                            globalFilter = this.value.trim().toLowerCase();
                            applyFilters();
                        });

                        document.getElementById('o_sd_clear_filters').addEventListener('click', function () {
                            columnFilters = {};
                            globalFilter = '';
                            globalSearchEl.value = '';
                            updateFilterButtonState();
                            applyFilters();
                        });

                        var columnsBtn = document.getElementById('o_sd_columns_btn');
                        columnsBtn.addEventListener('click', function (ev) {
                            ev.stopPropagation();
                            toggleColumnsPanel(columnsBtn);
                        });

                        // Click a row to keep it highlighted (same light-blue as
                        // hover) until another row is clicked, or the same row
                        // is clicked again to deselect it.
                        tbody.addEventListener('click', function (ev) {
                            var row = ev.target.closest('tr');
                            if (!row || row.parentNode !== tbody) { return; }
                            var alreadySelected = row.classList.contains('o_sd_row_selected');
                            rows.forEach(function (r) { r.classList.remove('o_sd_row_selected'); });
                            if (!alreadySelected) { row.classList.add('o_sd_row_selected'); }
                        });

                        applyFilters();
                    });
                //
